import { AnimatePresence, MotiView } from 'moti'
import { Text, TouchableOpacity, View } from 'react-native'
import { useChatStore } from '../../store/chatStore'
import {
	closeChatEmitter,
	CloseChatEvents,
	defineStyles,
	modeChangeEmitter,
	ModeChangeEvents,
	pathChangeEmitter,
	PathChangeEvents
} from '@/utils'
import { colors, Theme, useTheme } from '@/theme'
import { MobileViewIcon } from '@/screens/launcher-menu/components/MobileViewIcon'
import { WebViewIcon } from '@/screens/launcher-menu/components/WebViewIcon'
import { capitalize } from 'lodash'

const parseURL = (url: string) => {
	return capitalize(url.split('/').pop() || 'Home')
}

export const SummaryBlock = ({
	updates,
	isLatest,
	messageId,
	isLauncher
}: {
	updates: { device: 'mobile' | 'web'; url: string }[]
	isLatest: boolean
	messageId: string
	isLauncher: boolean
}) => {
	const { theme } = useTheme()
	const currentMessageId = useChatStore((state) => state.value.currentMessageId)
	const chatState = useChatStore((state) => state.value.chatState)

	if (currentMessageId === messageId && chatState === 'GENERATING') {
		return null
	}

	return (
		<AnimatePresence exitBeforeEnter>
			{updates?.length > 0 && (
				<MotiView
					from={{ opacity: 0 }}
					animate={{ opacity: isLatest ? 0 : 1 }}
					exit={{ opacity: 0 }}
					transition={{
						type: 'timing',
						duration: 500
					}}
					style={{ gap: 8, paddingHorizontal: 28 }}
				>
					<Text style={styles.updatesText(theme)}>UPDATES</Text>
					<View style={styles.updatesContainer(theme)}>
						{updates?.map((item, index) => (
							<TouchableOpacity
								key={item.url}
								onPress={() => {
									if (!isLauncher) return
									modeChangeEmitter.emit(ModeChangeEvents.MODE_CHANGE, {
										mode: item.device
									})
									pathChangeEmitter.emit(PathChangeEvents.PATH_CHANGE, {
										path: item.url
									})
									closeChatEmitter.emit(CloseChatEvents.CLOSE_CHAT)
								}}
								style={[
									styles.updateItem,
									index !== updates.length - 1 && {
										borderBottomWidth: 1,
										borderBottomColor: colors[theme].gray[75]
									}
								]}
							>
								{item.device === 'mobile' ? (
									<MobileViewIcon color={colors[theme].gray[400]} />
								) : (
									<WebViewIcon color={colors[theme].gray[400]} />
								)}
								<Text style={styles.updateItemText(theme)}>
									{parseURL(item.url)}
								</Text>
							</TouchableOpacity>
						))}
					</View>
				</MotiView>
			)}
		</AnimatePresence>
	)
}

const styles = defineStyles({
	updatesText: (theme: Theme) => ({
		fontSize: 12,
		fontWeight: '400',
		color: colors[theme].gray[500]
	}),
	updatesContainer: (theme: Theme) => ({
		borderWidth: 1,
		borderColor: colors[theme].gray[75],
		borderRadius: 8
	}),
	updateItem: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: 6,
		padding: 12
	},
	updateItemText: (theme: Theme) => ({
		fontSize: 14,
		fontWeight: '500',
		color: colors[theme].gray[500]
	})
})
